use clap::Parser;

#[derive(Parser, Debug)]
pub struct Args {
    /// Input file (optional). If not provided, reads from stdin (pipe)
    #[arg(short, long)]
    input: Option<String>,

    /// Struct name (default: "AutoGenerated")
    #[arg(short, long, default_value = "AutoGenerated")]
    name: String,

    /// Use json tags
    #[arg(long, default_value_t = true)]
    json: bool,
}
pub fn run(args: &Args) {
    println!("{:?}", args);
}
